export const bokaHtml = "<!DOCTYPE html>\n<html lang=\"is\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Bóka tíma – Nýsprautun</title>\n<style>\n  :root { --red: #c8102e; --ink: #16181d; --ink2: #4b5160; --line: #dfe2e8; font-family: Inter, system-ui, -apple-system, \"Segoe UI\", Roboto, Arial, sans-serif; color: var(--ink); }\n  * { box-sizing: border-box; }\n  body { margin: 0; background: transparent; }\n  .wrap { max-width: 640px; margin: 0 auto; padding: 20px 16px 32px; }\n  h1 { font-size: 26px; margin: 0 0 6px; }\n  p.lead { color: var(--ink2); margin: 0 0 22px; line-height: 1.5; }\n  form { display: grid; gap: 16px; }\n  .two { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }\n  label { display: grid; gap: 6px; font-weight: 600; font-size: 14px; }\n  label small { font-weight: 400; color: var(--ink2); }\n  input, select, textarea { font: inherit; padding: 11px 12px; border: 1px solid var(--line); border-radius: 8px; background: #fff; width: 100%; color: var(--ink); }\n  input:focus, select:focus, textarea:focus { outline: 3px solid rgba(200,16,46,.18); border-color: var(--red); }\n  textarea { min-height: 100px; resize: vertical; }\n  .plate { text-transform: uppercase; font-family: ui-monospace, Menlo, monospace; font-weight: 700; letter-spacing: 1px; }\n  .parts { display: flex; gap: 8px; flex-wrap: wrap; }\n  .parts label { display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); border-radius: 8px; padding: 10px 14px; cursor: pointer; font-weight: 500; }\n  .parts input { width: auto; accent-color: var(--red); }\n  .parts label:has(input:checked) { border-color: var(--red); background: #fff5f6; }\n  button { font: inherit; font-weight: 700; background: var(--red); color: #fff; border: 0; border-radius: 8px; padding: 14px 20px; cursor: pointer; font-size: 16px; }\n  button:hover { background: #a00d25; }\n  button[disabled] { opacity: .6; cursor: default; }\n  .err { color: #b91c1c; font-size: 14px; }\n  .note { font-size: 13px; color: var(--ink2); line-height: 1.5; }\n  .ok { text-align: center; padding: 40px 10px; }\n  .ok .tick { width: 64px; height: 64px; border-radius: 50%; background: #16a34a; color: #fff; display: grid; place-items: center; font-size: 34px; margin: 0 auto 16px; }\n  .hp { position: absolute; left: -9999px; }\n  @media (max-width: 560px) { .two { grid-template-columns: 1fr; } }\n</style>\n</head>\n<body>\n<div class=\"wrap\" id=\"root\">\n  <h1>Bóka tíma</h1>\n  <p class=\"lead\">Sendu okkur beiðni um tíma og við höfum samband til að staðfesta. Tíminn er ekki bókaður fyrr en staðfesting hefur borist.</p>\n  <form id=\"f\" novalidate>\n    <div class=\"two\">\n      <label>Nafn <input name=\"name\" required autocomplete=\"name\"></label>\n      <label>Símanúmer <input name=\"phone\" type=\"tel\" required autocomplete=\"tel\" inputmode=\"tel\"></label>\n    </div>\n    <div class=\"two\">\n      <label>Netfang <small>til að fá staðfestingu</small><input name=\"email\" type=\"email\" autocomplete=\"email\"></label>\n      <label>Bílnúmer <input name=\"plate\" class=\"plate\" required maxlength=\"8\" placeholder=\"AB123\"></label>\n    </div>\n    <label>Hvað þarf að gera? <select name=\"service_id\" id=\"svc\"><option value=\"\">— veldu —</option></select></label>\n    <div class=\"two\">\n      <label>Óskadagur <input name=\"preferred_date\" type=\"date\" id=\"d1\"></label>\n      <label>Varadagur <small>(valfrjálst)</small><input name=\"alt_date\" type=\"date\" id=\"d2\"></label>\n    </div>\n    <div>\n      <div style=\"font-weight:600;font-size:14px;margin-bottom:6px\">Tími dags</div>\n      <div class=\"parts\">\n        <label><input type=\"radio\" name=\"preferred_part\" value=\"any\" checked> Skiptir ekki máli</label>\n        <label><input type=\"radio\" name=\"preferred_part\" value=\"morning\"> Fyrir hádegi</label>\n        <label><input type=\"radio\" name=\"preferred_part\" value=\"afternoon\"> Eftir hádegi</label>\n      </div>\n    </div>\n    <label>Lýsing / athugasemdir <small>t.d. hvar tjónið er, tryggingafélag o.s.frv.</small><textarea name=\"notes\"></textarea></label>\n    <input class=\"hp\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" aria-hidden=\"true\">\n    <div class=\"err\" id=\"err\" role=\"alert\"></div>\n    <button id=\"send\" type=\"submit\">Senda beiðni</button>\n    <div class=\"note\" id=\"contact\"></div>\n  </form>\n</div>\n<script>\n(async () => {\n  const f = document.getElementById('f'), err = document.getElementById('err');\n  const pad = (n) => String(n).padStart(2, '0');\n  const ymd = (d) => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;\n  let o;\n  try { o = await fetch('/api/public/options').then((r) => r.json()); } catch { err.textContent = 'Ekki tókst að hlaða síðunni. Reyndu aftur.'; return; }\n  if (!o.enabled) {\n    document.getElementById('root').innerHTML = `<h1>Netbókun lokuð</h1><p class=\"lead\">Hafðu samband í síma ${o.shop.phone || ''}.</p>`;\n    return;\n  }\n  const svc = document.getElementById('svc');\n  for (const s of o.services) svc.add(new Option(s.name, s.id));\n  const now = new Date();\n  const min = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + o.minDays));\n  const max = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + o.maxDays));\n  for (const id of ['d1', 'd2']) { const el = document.getElementById(id); el.min = ymd(min); el.max = ymd(max); }\n  const closedWd = new Set(o.hours.filter((h) => h.closed).map((h) => h.weekday));\n  const isClosed = (s) => {\n    if (!s) return false;\n    const d = new Date(s + 'T00:00:00Z');\n    const wd = ((d.getUTCDay() + 6) % 7) + 1;\n    if (closedWd.has(wd)) return true;\n    return o.closures.some((c) => new Date(c.starts_at) <= d && new Date(c.ends_at) >= new Date(d.getTime() + 864e5));\n  };\n  if (o.shop.phone || o.shop.email) document.getElementById('contact').textContent = `Spurningar? Hringdu í ${o.shop.phone}${o.shop.email ? ' eða sendu póst á ' + o.shop.email : ''}.`;\n\n  f.addEventListener('submit', async (e) => {\n    e.preventDefault(); err.textContent = '';\n    const data = Object.fromEntries(new FormData(f));\n    if (!data.name || !data.phone || !data.plate) { err.textContent = 'Fylltu út nafn, símanúmer og bílnúmer.'; return; }\n    for (const k of ['preferred_date', 'alt_date']) {\n      if (data[k] && (data[k] < ymd(min) || data[k] > ymd(max))) { err.textContent = `Veldu dag á bilinu ${ymd(min)} til ${ymd(max)}.`; return; }\n      if (isClosed(data[k])) { err.textContent = 'Það er lokað þann dag sem þú valdir. Veldu annan dag.'; return; }\n    }\n    const btn = document.getElementById('send'); btn.disabled = true; btn.textContent = 'Sendi…';\n    try {\n      const r = await fetch('/api/public/request', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(data) });\n      const d = await r.json().catch(() => ({}));\n      if (!r.ok) throw new Error(d.error || 'Villa');\n      document.getElementById('root').innerHTML = `<div class=\"ok\"><div class=\"tick\">✓</div><h1>Takk fyrir!</h1><p class=\"lead\">Beiðnin þín er móttekin. Við höfum samband fljótlega til að staðfesta tímann${data.email ? ', og staðfesting á móttöku hefur verið send á netfangið þitt' : ''}.</p></div>`;\n      parent?.postMessage?.({ type: 'nysprautun-booking-sent' }, '*');\n    } catch (ex) {\n      err.textContent = ex.message; btn.disabled = false; btn.textContent = 'Senda beiðni';\n    }\n  });\n})();\n</script>\n</body>\n</html>\n";
